import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride, int padding, int dilation,
    int groups, int C_in_per_group, int C_out_per_group,
    bool has_bias)
{
    long total = (long)N * C_out * D_out * H_out * W_out;
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    if (idx >= total) return;

    // decode idx -> n, oc, h, w, d (matches output tensor layout N,C_out,H_out,W_out,D_out)
    long tmp = idx;
    int d_out = tmp % D_out; tmp /= D_out;
    int w_out = tmp % W_out; tmp /= W_out;
    int h_out = tmp % H_out; tmp /= H_out;
    int oc = tmp % C_out; tmp /= C_out;
    int n = tmp;

    int group_id = oc / C_out_per_group;
    int ic_start = group_id * C_in_per_group;

    float acc = 0.0f;

    int d_in_base = d_out * stride - padding;
    int h_in_base = h_out * stride - padding;
    int w_in_base = w_out * stride - padding;

    for (int ic = 0; ic < C_in_per_group; ++ic) {
        int in_c = ic_start + ic;
        const float* input_nc = input + (((long)n * C_in + in_c) * D_in * H_in * W_in);
        const float* weight_oc_ic = weight + (((long)oc * C_in_per_group + ic) * kD * kH * kW);

        for (int kd = 0; kd < kD; ++kd) {
            int d_in = d_in_base + kd * dilation;
            if (d_in < 0 || d_in >= D_in) continue;
            for (int kh = 0; kh < kH; ++kh) {
                int h_in = h_in_base + kh * dilation;
                if (h_in < 0 || h_in >= H_in) continue;
                for (int kw = 0; kw < kW; ++kw) {
                    int w_in = w_in_base + kw * dilation;
                    if (w_in < 0 || w_in >= W_in) continue;

                    float in_val = input_nc[((long)h_in * W_in + w_in) * D_in + d_in];
                    float w_val = weight_oc_ic[(kd * kH + kh) * kW + kw];
                    acc += in_val * w_val;
                }
            }
        }
    }

    if (has_bias) {
        acc += bias[oc];
    }

    output[idx] = acc;
}

torch::Tensor conv3d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);
    int D_in = input.size(4);

    int C_out = weight.size(0);
    int C_in_per_group = weight.size(1);
    int kH = weight.size(2);
    int kW = weight.size(3);
    int kD = weight.size(4);

    int C_out_per_group = C_out / groups;

    int H_out = (H_in + 2 * padding - dilation * (kH - 1) - 1) / stride + 1;
    int W_out = (W_in + 2 * padding - dilation * (kW - 1) - 1) / stride + 1;
    int D_out = (D_in + 2 * padding - dilation * (kD - 1) - 1) / stride + 1;

    auto output = torch::zeros({N, C_out, H_out, W_out, D_out}, input.options());

    // Note: our kernel indexing treats spatial dims in order (D, H, W) matching
    // tensor layout (N, C, H, W, D) memory layout where last dim is D (contiguous fastest).
    // We need to map correctly: input tensor is (N, C, H, W, D) contiguous.
    // We'll reinterpret dims as D_in=depth(last dim), H_in=height, W_in=width but
    // physical strides must match. Let's recompute strides manually instead.

    long total = (long)N * C_out * D_out * H_out * W_out;
    int threads = 256;
    long blocks = (total + threads - 1) / threads;

    const float* bias_ptr = has_bias ? bias.contiguous().data_ptr<float>() : nullptr;

    conv3d_forward_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        stride, padding, dilation,
        groups, C_in_per_group, C_out_per_group,
        has_bias
    );

    return output;
}
"""

